import { FilterDataAccessor } from 'domain/Filter';
import type {
  FilterDataStructure,
  FilterForm,
  FilterValue,
} from 'models/Filters';

import {
  getSubBrands,
  hasSingleSubBrand,
  hasSpecificValue,
} from './utils/resolveCommercialResultsWaterfallOptions';

/** Dimensions scoped by selected brand on Commercial Results only. */
export const COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS = [
  'region',
  'channel',
  'pack_type',
] as const;

export type CommercialBrandDependentDimensionKey =
  (typeof COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS)[number];

const isBaselineAll = (value: FilterValue | undefined): boolean => {
  if (value == null || value === '') return true;
  return String(value).toUpperCase() === 'ALL';
};

const getDefaultForDimension = (
  dataFilters: FilterDataStructure,
  key: CommercialBrandDependentDimensionKey,
): FilterValue | null => {
  const block = dataFilters[key];
  return block?.default?.value ?? null;
};

const isValueValidForDimension = (
  dataFilters: FilterDataStructure,
  form: FilterForm,
  key: CommercialBrandDependentDimensionKey,
  value: FilterValue | undefined,
): boolean => {
  if (isBaselineAll(value)) return true;

  const options = FilterDataAccessor.getInstance().getOptions(
    key,
    dataFilters,
    form,
  );

  if (!options.length) return false;

  return options.some((option) => String(option.value) === String(value));
};

/**
 * Resets region/channel/pack_type to preset baseline when the current value
 * is not in the option list (e.g. after brand-scoped preset refresh).
 * Also auto-selects sub_brand when the selected brand has only one sub-brand.
 */
export function reconcileCommercialBrandDependentDimensions(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  const next: FilterForm = { ...form };

  for (const key of COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS) {
    const current = next[key];
    if (isValueValidForDimension(dataFilters, next, key, current)) {
      continue;
    }
    next[key] = getDefaultForDimension(dataFilters, key);
  }

  if (
    hasSpecificValue(next.brands) &&
    hasSingleSubBrand(dataFilters, next.brands)
  ) {
    const singleSubBrand = getSubBrands(dataFilters)[0]?.value ?? 'All';

    if (next.sub_brands !== singleSubBrand) {
      next.sub_brands = singleSubBrand;
    }
  }

  return next;
}

/**
 * Clears brand-dependent dimensions when the user picks a different brand
 * in the Commercial Results drawer (before Apply).
 */
export function cascadeCommercialBrandDependentDimensionsToBaseline(
  dataFilters: FilterDataStructure,
  form: FilterForm,
): FilterForm {
  const next: FilterForm = { ...form };

  for (const key of COMMERCIAL_BRAND_DEPENDENT_DIMENSION_KEYS) {
    next[key] = getDefaultForDimension(dataFilters, key) ?? 'All';
  }

  return next;
}
